// Code «Preparar panel» (12 · Panel de Marisa) · Run Once for All Items
// Lee las tres listas de la API y devuelve un item { html } con el panel.
// No recalcula `abonado` ni `pendiente` de ningún apartado: suma el `pendiente` que da la app.

const ZONA = 'Europe/Madrid';
const FORMAS = ['efectivo', 'tarjeta', 'bizum'];
const NOMBRE_FORMA = { efectivo: 'Efectivo', tarjeta: 'Tarjeta', bizum: 'Bizum' };
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const DIAS_AVISO = 7;

// Hoy y día 1 en la zona de la tienda; son los mismos que usan las URL de los tres GET
const ahora = DateTime.now().setZone(ZONA);
const hoyDia = ahora.startOf('day');
const hoy = hoyDia.toFormat('yyyy-MM-dd');
const desde = hoyDia.startOf('month').toFormat('yyyy-MM-dd');
const limiteAviso = hoyDia.plus({ days: DIAS_AVISO }).toFormat('yyyy-MM-dd');

// Items de un GET sin el item vacío de Always Output Data (no tiene `id`)
const leer = nombre => $(nombre).all().map(i => i.json).filter(j => j && j.id != null);

const ventasMes = leer('Leer ventas del mes').filter(v => v.fecha >= desde && v.fecha <= hoy);
const abonosMes = leer('Leer abonos del mes').filter(b => b.fecha >= desde && b.fecha <= hoy);
const activos = leer('Leer apartados activos').filter(a => a.estado === 'activo');

// Importes en céntimos para sumar sin decimales raros; se muestran como 1.234,56 €
const cent = x => Math.round(Number(x) * 100);
function eur(c) {
  const signo = c < 0 ? '-' : '';
  const abs = Math.abs(c);
  const enteros = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return `${signo}${enteros},${String(abs % 100).padStart(2, '0')} €`;
}
const fecha = f => (f ? String(f).split('-').reverse().join('/') : '');
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Suma total y por forma de pago
function sumar(lista) {
  const r = { n: lista.length, total: 0 };
  for (const f of FORMAS) r[f] = 0;
  for (const x of lista) {
    const c = cent(x.importe);
    r.total += c;
    if (FORMAS.includes(x.forma_pago)) r[x.forma_pago] += c;
  }
  return r;
}
function juntar(a, b) {
  const r = { n: a.n + b.n, total: a.total + b.total };
  for (const f of FORMAS) r[f] = a[f] + b[f];
  return r;
}

const hoyV = sumar(ventasMes.filter(v => v.fecha === hoy));
const hoyA = sumar(abonosMes.filter(b => b.fecha === hoy));
const hoyT = juntar(hoyV, hoyA);
const mesV = sumar(ventasMes);
const mesA = sumar(abonosMes);
const mesT = juntar(mesV, mesA);

// Pendiente de cobro: suma del `pendiente` de la app de los apartados activos
const pendiente = activos.reduce((s, a) => s + cent(a.pendiente), 0);

// Días entre hoy y la fecha límite (0 = vence hoy; negativo = fuera de plazo)
const dias = f => Math.round(DateTime.fromISO(String(f), { zone: ZONA }).startOf('day').diff(hoyDia, 'days').days);
const porLimite = (a, b) => (a.fecha_limite < b.fecha_limite ? -1 : a.fecha_limite > b.fecha_limite ? 1 : a.id - b.id);

// Vencen pronto: fecha_limite entre hoy y hoy + 7. Fuera de plazo: fecha_limite anterior a hoy (los vence el 06)
const pronto = activos.filter(a => a.fecha_limite >= hoy && a.fecha_limite <= limiteAviso).sort(porLimite);
const fuera = activos.filter(a => a.fecha_limite < hoy).sort(porLimite);

// ---------- HTML ----------

const tarjeta = (titulo, cifra, detalle, clase = '') =>
  `<section class="tarjeta ${clase}"><h2>${titulo}</h2><p class="cifra">${cifra}</p>${detalle}</section>`;

const desglose = s => `<ul class="desglose">${FORMAS.map(f =>
  `<li><span>${NOMBRE_FORMA[f]}</span><span>${eur(s[f])}</span></li>`).join('')}</ul>`;

const lineas = (filas) => `<ul class="desglose">${filas.map(([t, v]) =>
  `<li><span>${t}</span><span>${v}</span></li>`).join('')}</ul>`;

const operaciones = n => `${n} ${n === 1 ? 'operación' : 'operaciones'}`;

function cuandoVence(d) {
  if (d === 0) return 'Vence hoy';
  if (d === 1) return 'Vence mañana';
  if (d > 1) return `Faltan ${d} días`;
  return `Venció hace ${-d} ${d === -1 ? 'día' : 'días'}`;
}

const apartado = (a, clase) => {
  const d = dias(a.fecha_limite);
  const talla = a.talla ? `, talla ${esc(a.talla)}` : '';
  return `<li class="apartado ${clase}">`
    + `<div class="fila"><strong>${esc(a.cliente)}</strong><span class="etiqueta">${cuandoVence(d)}</span></div>`
    + `<div>${esc(a.producto)}${talla} · nº ${esc(a.id)}</div>`
    + `<div class="fila"><span>Pendiente: <strong>${eur(cent(a.pendiente))}</strong></span>`
    + `<span>Hasta el ${fecha(a.fecha_limite)}</span></div></li>`;
};

const lista = (items, clase, vacio) => (items.length
  ? `<ul class="apartados">${items.map(a => apartado(a, clase)).join('')}</ul>`
  : `<p class="vacio">${vacio}</p>`);

const nombreMes = `${MESES[hoyDia.month - 1]} de ${hoyDia.year}`;
const hoyTexto = hoyT.n ? `${operaciones(hoyT.n)}` : 'Hoy todavía no hay cobros';

const css = `
*{box-sizing:border-box}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
background:#f4f3ef;color:#1f2a24;font-size:16px;line-height:1.4}
header{background:#2f6f5e;color:#fff;padding:16px}
header h1{margin:0;font-size:22px}
header p{margin:4px 0 0;font-size:14px;opacity:.9}
main{max-width:960px;margin:0 auto;padding:16px}
.tarjetas{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}
.tarjeta{background:#fff;border-radius:12px;padding:16px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.tarjeta h2{margin:0;font-size:15px;font-weight:600;color:#55605a;text-transform:uppercase;letter-spacing:.03em}
.cifra{margin:6px 0 8px;font-size:34px;font-weight:700;white-space:nowrap}
.destacada{border-left:6px solid #2f6f5e}
.aviso{border-left:6px solid #c27c0e}
.desglose{list-style:none;margin:0;padding:0;font-size:15px}
.desglose li{display:flex;justify-content:space-between;gap:8px;padding:3px 0;border-top:1px solid #eee}
.nota{margin:6px 0 0;font-size:13px;color:#66706a}
h2.seccion{margin:24px 0 8px;font-size:19px}
.apartados{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.apartado{background:#fff;border-radius:10px;padding:12px;box-shadow:0 1px 3px rgba(0,0,0,.08);border-left:6px solid #c27c0e}
.apartado.fuera{border-left-color:#b23b2e}
.fila{display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px 12px}
.etiqueta{font-size:14px;font-weight:600;color:#8a5a08}
.fuera .etiqueta{color:#b23b2e}
.vacio{background:#fff;border-radius:10px;padding:12px;color:#66706a}
footer{max-width:960px;margin:0 auto;padding:8px 16px 24px;font-size:13px;color:#66706a}
`;

const html = `<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Panel · Paso Firme</title>
<style>${css}</style>
</head>
<body>
<header>
<h1>Paso Firme · Panel de Marisa</h1>
<p>Actualizado el ${ahora.toFormat('dd/MM/yyyy')} a las ${ahora.toFormat('HH:mm')}. Recarga la página para ver los datos al momento.</p>
</header>
<main>
<div class="tarjetas">
${tarjeta(`Cobrado hoy · ${fecha(hoy)}`, eur(hoyT.total),
    lineas([['Ventas directas', eur(hoyV.total)], ['Abonos', eur(hoyA.total)]]) + desglose(hoyT)
    + `<p class="nota">${hoyTexto}</p>`, 'destacada')}
${tarjeta(`Recaudado en ${nombreMes}`, eur(mesT.total),
    lineas([['Ventas directas', eur(mesV.total)], ['Abonos', eur(mesA.total)]]) + desglose(mesT)
    + `<p class="nota">Del ${fecha(desde)} al ${fecha(hoy)} · ${operaciones(mesT.n)}. Los abonos incluyen los iniciales.</p>`)}
${tarjeta('Pendiente de cobro', eur(pendiente),
    `<p class="nota">En ${activos.length} ${activos.length === 1 ? 'apartado activo' : 'apartados activos'}.</p>`, 'aviso')}
</div>
<h2 class="seccion">Vencen en los próximos ${DIAS_AVISO} días (${pronto.length})</h2>
${lista(pronto, 'pronto', `Ningún apartado vence hasta el ${fecha(limiteAviso)}.`)}
<h2 class="seccion">Fuera de plazo, todavía activos (${fuera.length})</h2>
${fuera.length ? '<p class="nota">Se vencen solos cada mañana a las 9:00 y el cliente recibe su vale.</p>' : ''}
${lista(fuera, 'fuera', 'Ninguno.')}
</main>
<footer>Cifras de la app de la tienda. Los importes pendientes son los que calcula la app.</footer>
</body>
</html>`;

return [{ json: { html } }];
